package org.example.idf_service.service;
import org.example.idf_service.domain.ExchangeRate; import org.example.idf_service.repository.RateRepository; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.math.*; import java.time.*; import java.util.Map;
@Service public class RateService { private final RateRepository rates; private final RestClient client; public RateService(RateRepository rates,RestClient client){this.rates=rates;this.client=client;}
 public BigDecimal usdRate(String currency, LocalDate date) { if("USD".equals(currency)) return BigDecimal.ONE; return rates.findFirstByCurrencyAndRateDateLessThanEqualOrderByRateDateDesc(currency,date).map(ExchangeRate::getUsdRate).orElseGet(()->fetch(currency,date)); }
 @SuppressWarnings("unchecked") private BigDecimal fetch(String currency, LocalDate date) { Exception failure = null; for (int attempt = 0; attempt < 2; attempt++) { try { Map<String,Object> body=client.get().uri(uri->uri.path("/v1/{date}").queryParam("base",currency).queryParam("symbols","USD").build(date)).retrieve().body(Map.class); Object v=((Map<String,Object>)body.get("rates")).get("USD"); BigDecimal rate=new BigDecimal(v.toString()).setScale(8,RoundingMode.HALF_UP); rates.save(new ExchangeRate(currency,date,rate,"frankfurter")); return rate; } catch(Exception e){ failure=e; } } throw new RateUnavailableException(currency,date,failure); }
}
